**第 12 题** 下面 `count_triple` 函数的时间复杂度为 (     )。

```cpp
01 int gcd(int m, int n) {
02     if (m == 0) return n;
03     return gcd(n % m, m);
04 }
05 int count_triple(int n) {
06     int cnt = 0;
07     for (int v = 1; v * v * 4 <= n; v++)
08         for (int u = v + 1; u * (u + v) * 2 <= n; u += 2)
09             if (gcd(u, v) == 1) {
10                 int a = u * u - v * v;
11                 int b = u * v * 2;
12                 int c = u * u + v * v;
13                 cnt += n / (a + b + c);
14         }
15     return cnt;
16 }
```

