#include <iostream>
#include <vector>
#include <climits>
using namespace std;
int prim(vector<vector<int>>& graph, int n) {
    vector<int> key(n, INT_MAX), parent(n, -1);
    vector<bool> inMST(n, false);
    key[0] = 0;
    for (int i = 0; i < n; ++i) {
        int u = -1;
        for (int v = 0; v < n; ++v)
            if (!inMST[v] && (u == -1 || key[v] < key[u])) u = v;
        if (u == -1 || key[u] == INT_MAX) return -1;
        inMST[u] = true;
        for (int v = 0; v < n; ++v)
            if (!inMST[v]) {
                if (________________) { // 填入选项
                    key[v] = graph[u][v]; parent[v] = u;
                }
            }
    }
    int sum = 0;
    for (int i = 0; i < n; ++i)
        if (parent[i] != -1) sum += key[i];
    return sum;
}
